<script setup lang="ts">
// AI 审阅产出分型只读渲染卡片：摘要 / 标签 / 难度 / 质量 / 建议。
// 供「AI 审阅产出详情」页展示各类产出，保证展示口径一致。
import { computed, ref, watch } from "vue";
import { gradeName, severityText } from "./enrich-common";

const props = defineProps<{
  taskType: string;
  payload: Record<string, unknown>;
  // 这里不再提供元信息行：可见性 / 来源 / 置信度由详情页卡片头统一渲染（那里还要与版本
  // 切换器同排），卡片内再实现一份会与它漂移，也会给「AI 产出」这个主流情况挂上多余标签。
  showEvidence?: boolean; // 难度/质量证据的**初始**展开状态；展开后由用户在卡片内自行控制
}>();

// 模板里放宽类型，便于直接取字段
const p = (): any => props.payload ?? {};

// 证据折叠：难度 evidence 与质量 evidence + 两轮评审 review 的篇幅都很长，
// 五类产出要一屏看全时默认折叠，需要深挖某一条时再展开。
// showEvidence 只决定初始态——否则父组件每次轮询刷新都会把用户刚展开的证据收回去。
const evidenceOpen = ref(props.showEvidence ?? false);
watch(
  () => props.showEvidence,
  (v) => {
    evidenceOpen.value = !!v;
  }
);

// 非空对象判断：payload 里 evidence 可能是 {}，此时没有可展开的内容，不该渲染开关
const hasKeys = (o: unknown): boolean => !!o && typeof o === "object" && Object.keys(o as object).length > 0;

// 只有难度/质量带可折叠的证据块，其余类型不渲染开关
const hasEvidence = computed(() => {
  const payload = p();
  if (props.taskType === "difficulty") {
    return hasKeys(payload.evidence);
  }
  if (props.taskType === "quality") {
    return hasKeys(payload.evidence) || !!payload.review;
  }
  return false;
});

const toggleEvidence = () => {
  evidenceOpen.value = !evidenceOpen.value;
};

const severityTheme = (s: string): string =>
  s === "block" ? "danger" : s === "warn" ? "warning" : "default";

// 证据维度键名中文化
const evidenceLabel: Record<string, string> = {
  thinking: "思维难度",
  algorithm: "算法要求",
  implementation: "实现难度",
  pitfalls: "陷阱密度",
  completeness: "题面完整性",
  statement: "题面表述",
  examples: "样例充分性",
  judge_config: "判题配置",
  data_strength: "数据强度",
  novelty: "创新性",
};

// 建议维度键名中文化
const dimensionText: Record<string, string> = {
  constraints: "数据范围/约束",
  io: "输入输出",
  examples: "样例",
  judge_config: "判题配置",
  data: "测试数据",
  statement: "题面表述",
};

// 质量各维度评分来源中文化
const sourceDesc: Record<string, string> = {
  rule: "规则",
  model: "模型",
  "rule+model": "规则+模型",
  "data:submit_distribution": "提交分布",
  "data:insufficient": "数据不足",
};
</script>

<template>
  <div class="annotation-card">
    <!-- 摘要 -->
    <template v-if="taskType === 'summary'">
      <div class="ac-line"><span class="ac-label">题意：</span>{{ p().oneliner }}</div>
      <div class="ac-line"><span class="ac-label">输入输出：</span>{{ p().io_points }}</div>
      <div class="ac-line"><span class="ac-label">规模：</span>{{ p().scale }}</div>
    </template>

    <!-- 标签 -->
    <template v-else-if="taskType === 'tags'">
      <t-space size="small" break-line>
        <t-tag v-for="t in p().canonical || []" :key="`c${t}`" theme="success" variant="light">
          {{ t }}
        </t-tag>
        <t-tag v-for="t in p().raw || []" :key="`r${t}`" variant="outline">{{ t }}</t-tag>
        <span v-if="!(p().canonical || []).length && !(p().raw || []).length" class="ac-meta-text">
          无标签
        </span>
      </t-space>
    </template>

    <!-- 难度 -->
    <template v-else-if="taskType === 'difficulty'">
      <div class="ac-line">
        <t-tag theme="primary" variant="dark">{{ gradeName(p().overall) }}</t-tag>
        <span class="ac-dims">
          思维 {{ p().thinking }} · 算法 {{ p().algorithm }} · 实现 {{ p().implementation }} · 陷阱
          {{ p().pitfalls }}
        </span>
      </div>
      <t-button
        v-if="hasEvidence"
        class="ac-evidence-toggle"
        size="small"
        variant="text"
        theme="primary"
        @click="toggleEvidence"
      >
        {{ evidenceOpen ? "收起推理依据" : "展开推理依据" }}
      </t-button>
      <div v-if="evidenceOpen && p().evidence" class="ac-evidence">
        <div v-for="(v, k) in p().evidence" :key="k" v-show="v" class="ac-evidence-row">
          <span class="ac-label">{{ evidenceLabel[String(k)] || k }}：</span>{{ v }}
        </div>
      </div>
    </template>

    <!-- 质量 -->
    <template v-else-if="taskType === 'quality'">
      <div class="ac-line">
        <t-tag theme="primary" variant="dark">{{ p().overall }} 分</t-tag>
        <span class="ac-dims">
          完整性 {{ p().completeness }} · 表述 {{ p().statement }} · 样例 {{ p().examples }} · 数据强度
          {{ p().data_strength }} · 判题配置 {{ p().judge_config }} · 创新 {{ p().novelty }}
        </span>
      </div>
      <!-- 各维度评分来源（规则/模型/提交数据）：让评分有据可查 -->
      <div v-if="p().sources" class="ac-sources">
        <span
          v-for="(src, k) in p().sources"
          :key="k"
          class="ac-source-item"
          :title="sourceDesc[String(src)] || String(src)"
        >
          {{ evidenceLabel[String(k)] || k }}：{{ sourceDesc[String(src)] || src }}
        </span>
      </div>
      <t-button
        v-if="hasEvidence"
        class="ac-evidence-toggle"
        size="small"
        variant="text"
        theme="primary"
        @click="toggleEvidence"
      >
        {{ evidenceOpen ? "收起推理依据" : "展开推理依据" }}
      </t-button>
      <div v-if="evidenceOpen && p().evidence" class="ac-evidence">
        <div v-for="(v, k) in p().evidence" :key="k" v-show="v" class="ac-evidence-row">
          <span class="ac-label">{{ evidenceLabel[String(k)] || k }}：</span>{{ v }}
        </div>
      </div>
      <!-- 两轮评审发现（做题人视角 + 命题人视角） -->
      <div v-if="evidenceOpen && p().review" class="ac-evidence">
        <div v-if="!p().review.solvable && p().review.solvable_note" class="ac-evidence-row">
          <span class="ac-label">可解性：</span>{{ p().review.solvable_note }}
        </div>
        <div v-for="(a, i) in p().review.ambiguities || []" :key="`a${i}`" class="ac-evidence-row">
          <span class="ac-label">歧义[{{ severityText[String(a.severity)] || a.severity }}]：</span>{{ a.evidence }} → {{ a.detail }}
        </div>
        <div v-for="(c, i) in p().review.sample_checks || []" :key="`s${i}`" class="ac-evidence-row">
          <span class="ac-label">样例推演[{{ c.ref }}]：</span>
          <span :class="{ 'ac-bad': !c.ok }">{{ c.ok ? '一致' : '不一致' }}</span> {{ c.note }}
        </div>
        <div v-if="p().review.data_range" class="ac-evidence-row">
          <span class="ac-label">数据范围：</span>{{ p().review.data_range }}
        </div>
        <div v-if="p().review.novelty_note" class="ac-evidence-row">
          <span class="ac-label">创新性：</span>{{ p().review.novelty_note }}
        </div>
        <div v-for="(f, i) in p().review.judge_risks || []" :key="`j${i}`" class="ac-evidence-row">
          <span class="ac-label">判题风险[{{ severityText[String(f.severity)] || f.severity }}]：</span>{{ f.evidence }} → {{ f.detail }}
        </div>
      </div>
    </template>

    <!-- 改进建议 -->
    <template v-else-if="taskType === 'suggestion'">
      <div v-for="(s, i) in p().items || []" :key="i" class="ac-sugg">
        <div class="ac-sugg-head">
          <t-tag size="small" theme="primary" variant="outline">{{ dimensionText[String(s.dimension)] || s.dimension }}</t-tag>
          <t-tag size="small" :theme="severityTheme(s.severity)" variant="light">
            {{ severityText[String(s.severity)] || s.severity }}
          </t-tag>
        </div>
        <span class="ac-sugg-text">{{ s.suggestion }}</span>
        <div v-if="s.evidence" class="ac-sugg-evidence" :title="s.evidence">{{ s.evidence }}</div>
      </div>
      <div v-if="!(p().items || []).length" class="ac-meta-text">无改进建议</div>
    </template>

    <div v-else class="ac-meta-text">未知产出类型：{{ taskType }}</div>
  </div>
</template>

