  display: flex;
  align-items: baseline;
  gap: 8px;
  flex-wrap: wrap;
}

.ac-label {
  color: var(--td-text-color-secondary);
  flex: none;
}

.ac-dims {
  font-size: 12px;
  color: var(--td-text-color-secondary);
}

.ac-evidence {
  margin-top: 6px;
  font-size: 12px;
  color: var(--td-text-color-secondary);
  border-left: 2px solid var(--td-border-level-2-color);
  padding-left: 8px;
}

/* 证据展开开关：贴在被它控制的内容正上方，压缩 TDesign 文本按钮的默认高度 */
.ac-evidence-toggle {
  margin-top: 2px;
  padding: 0;
  height: 22px;
  font-size: 12px;
